{
  "logline": "嵐の入り江の灯台で、灯台守の娘・澪は姉の死にまつわる鍵の行方を知ろうとするが、灯りを離れるあいだ船が危うくなるため、追うか守るかの選択を迫られる。",
  "premise": "嵐の夜、澪は入り江に避難した船頭のトキに鍵を貸す。その鍵が三年前に死んだ姉・汐に結びつくと知り、灯りを父に託して港町へ行方を追う。戻った澪は再びの嵐の中で、姉が守った灯りを自分の意志で守り直す。",
  "theme": "真相の追及対灯りを守る務め",
  "elements": {
    "who": "灯台守の娘・澪",
    "where": "嵐の入り江の灯台",
    "wants": "姉の死にまつわる鍵の行方を知ろうとする",
    "obstacle": "灯りを離れるあいだ船が危うくなる"
  },
  "similar": [
    {"title": "嵐の夜に灯台を守る若者の話", "axis": "structure", "difference": "鍵を追って往く中盤と戻って守る終盤の二つの動きで構成し、留守の危険を緊張に変える点"},
    {"title": "姉の遺品を辿る妹の物語", "axis": "character", "difference": "主人公が灯台守としての務めを負っており、探求そのものが務めを危うくする点"},
    {"title": "入り江の村を舞台にした海の民話", "axis": "world", "difference": "嵐の夜に灯りを消してはいけないという掟を世界の約束事として前面に置く点"}
  ],
  "prohibitions": [
    {"rule": "死んだ人物を行為者として登場させない", "check_ja": "各章で汐の名を含む文を確認し、言及と回想以外で動作の主語になっていないことを数える"},
    {"rule": "開示章より前に未開示の事実の語を使わない", "check_ja": "canonのfacts.setupと各章を照合し、設定章より前の章にtermsの語が無いことを確認する"},
    {"rule": "移動には場所間の移動日数以上をかける", "check_ja": "連続する章のdayの差とtravel_daysを比べ、差が移動日数を下回らないことを確認する"}
  ],
  "failure_questions": [
    "鍵の行方は最後まで回収されているか？",
    "追うか守るかの選択は最終章で本人の意志として示されているか？"
  ],
  "genre": "fantasy",
  "audience": "短編の海辺の幻想譚を好む読者"
}
